import{_ as t,c as i,a0 as s,o}from"./chunks/framework.BGabeMLJ.js";const a="/images/ui_images/hub_robots.png",n="/images/ui_images/hub_robots_details.png",r="/images/ui_images/hub_robots_roles.png",l="/images/ui_images/hub_robots_permissions.png",h="/images/ui_images/hub_robots_add.png",f=JSON.parse('{"title":"Clients","description":"","frontmatter":{},"headers":[],"relativePath":"guide/admin/clients.md","filePath":"guide/admin/clients.md"}'),c={name:"guide/admin/clients.md"};function g(m,e,d,u,p,b){return o(),i("div",null,e[0]||(e[0]=[s('<h1 id="clients" tabindex="-1">Clients <a class="header-anchor" href="#clients" aria-label="Permalink to &quot;Clients&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Notice</p><p>In order to manage your identity-providers, nodes, ... you need to get an organization. Please contact us, such we can provide you a realm in which you can manage all your nodes, users and identity providers. For more details on realms click <a href="/guide/admin/realms.html">here</a>.</p></div><p>Clients may be freely created and edited by the admin. They are pseudo-users, which are handled directly by the API, meaning that you will not be able to login in the central App with their credentials. This allows for slightly faster automatized pipeline executions for the PHT&#39;s functions.</p><ol><li>Within the admin area (top left), you need to select <strong>Clients</strong> within the left navigation. <a href="/images/ui_images/hub_robots.png"><img src="'+a+'" alt="image"></a></li><li><strong>View</strong> existing clients (Optional: Use the search bar at the top).</li><li><strong>See/Edit details</strong> for each client by clicking the blue triple-bar button on the right. Doing so shows the general description of the client. <a href="/images/ui_images/hub_robots_details.png"><img src="'+n+'" alt="image"></a> You may also specify realms of other users if you wish to make it accessible for them.<br> You can furthermore specify the roles and associated permissions of the client with the tabs on top under its name to ensure it does not have any authorities beyond the ones necessary for its functionalities. For this, roles describe a rough outline specifically targeted at the admin&#39;s own realm.<br><a href="/images/ui_images/hub_robots_roles.png"><img src="'+r+'" alt="image"></a><br> If the client is shared though, it is useful to declare the underlying permissions in order to ensure it is working in other realms as well (as the permissions of their roles may vary).<br><a href="/images/ui_images/hub_robots_permissions.png"><img src="'+l+'" alt="image"></a><br> Adding either roles or permissions to the client is done by clicking the green plus-symbol on the right. Vice-versa, roles and permissions can be removed from the client by clicking the red trashcan-button there.</li><li><strong>Delete</strong> clients by clicking the red trash can button on the right.</li><li><strong>Add</strong> clients by clicking the grey plus button on the left of the overview. For this, a name and description of the client have to be given. <a href="/images/ui_images/hub_robots_add.png"><img src="'+h+'" alt="image"></a></li><li><strong>Refresh</strong> this list anytime by clicking the black refresh button on the top right.</li></ol>',4)]))}const y=t(c,[["render",g]]);export{f as __pageData,y as default};
